"use client"

import * as React from "react"
import * as SelectPrimitive from "@radix-ui/react-select"
import { Check, ChevronDown, ChevronUp, Search } from "lucide-react"

import { cn } from "@/lib/utils"

const Select = SelectPrimitive.Root

const SelectGroup = SelectPrimitive.Group

const SelectValue = SelectPrimitive.Value

const SelectTrigger = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger>
>(({ className, children, ...props }, ref) => (
  <SelectPrimitive.Trigger
    ref={ref}
    className={cn(
      "flex h-10 w-full items-center justify-between whitespace-nowrap rounded-[8px] border border-[#e6e6e6] bg-white px-3 py-2 text-[14px] leading-[20px] text-[#111111] shadow-none",
      "data-[placeholder]:text-[#b3b3b3] [&>span]:line-clamp-1",
      "focus-visible:outline-none focus-visible:border-[#1D1C20] data-[state=open]:border-[#1D1C20]",
      "disabled:cursor-not-allowed disabled:bg-[#f2f2f2] disabled:text-[#9ca3af] disabled:data-[placeholder]:text-[#b3b3b3]",
      "aria-invalid:border-[#ff3b30] aria-invalid:focus-visible:border-[#ff3b30]",
      className
    )}
    {...props}
  >
    {children}
    <SelectPrimitive.Icon asChild>
      <ChevronDown className="h-4 w-4 text-[#7f7d83]" />
    </SelectPrimitive.Icon>
  </SelectPrimitive.Trigger>
))
SelectTrigger.displayName = SelectPrimitive.Trigger.displayName

const SelectScrollUpButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollUpButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollUpButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollUpButton
    ref={ref}
    className={cn(
      "flex cursor-default items-center justify-center py-1 text-[#7f7d83]",
      className
    )}
    {...props}
  >
    <ChevronUp className="h-4 w-4" />
  </SelectPrimitive.ScrollUpButton>
))
SelectScrollUpButton.displayName = SelectPrimitive.ScrollUpButton.displayName

const SelectScrollDownButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollDownButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollDownButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollDownButton
    ref={ref}
    className={cn(
      "flex cursor-default items-center justify-center py-1 text-[#7f7d83]",
      className
    )}
    {...props}
  >
    <ChevronDown className="h-4 w-4" />
  </SelectPrimitive.ScrollDownButton>
))
SelectScrollDownButton.displayName =
  SelectPrimitive.ScrollDownButton.displayName

type SelectContentProps = React.ComponentPropsWithoutRef<
  typeof SelectPrimitive.Content
> & {
  enableSearch?: boolean
  searchPlaceholder?: string
  searchValue?: string
  onSearchValueChange?: (value: string) => void
}

type SelectSearchContextValue = {
  enabled: boolean
  query: string
}

const SelectSearchContext = React.createContext<SelectSearchContextValue>({
  enabled: false,
  query: "",
})

const getNodeText = (node: React.ReactNode): string => {
  if (typeof node === "string" || typeof node === "number") {
    return String(node)
  }

  if (Array.isArray(node)) {
    return node.map(getNodeText).join(" ")
  }

  if (React.isValidElement(node)) {
    const element = node as React.ReactElement<{ children?: React.ReactNode }>
    return getNodeText(element.props.children)
  }

  return ""
}

const SelectContent = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Content>,
  SelectContentProps
>(
  (
    {
      className,
      children,
      position = "popper",
      enableSearch = false,
      searchPlaceholder = "Search...",
      searchValue,
      onSearchValueChange,
      ...props
    },
    ref
  ) => {
    const [localSearchValue, setLocalSearchValue] = React.useState("")
    const searchInputRef = React.useRef<HTMLInputElement | null>(null)
    const setSearchInputRef = React.useCallback(
      (node: HTMLInputElement | null) => {
        searchInputRef.current = node
        if (!node || !enableSearch) {
          return
        }
        window.requestAnimationFrame(() => {
          node.focus()
        })
      },
      [enableSearch]
    )

    const currentSearchValue = searchValue ?? localSearchValue
    const normalizedSearchValue = currentSearchValue.trim().toLowerCase()
    const searchContextValue = React.useMemo(
      () => ({
        enabled: enableSearch,
        query: normalizedSearchValue,
      }),
      [enableSearch, normalizedSearchValue]
    )

    const handleSearchChange: React.ChangeEventHandler<HTMLInputElement> = (
      event
    ) => {
      const nextValue = event.target.value
      if (searchValue === undefined) {
        setLocalSearchValue(nextValue)
      }
      onSearchValueChange?.(nextValue)
    }

    return (
      <SelectPrimitive.Portal>
        <SelectPrimitive.Content
          ref={ref}
          className={cn(
            "relative z-50 max-h-[--radix-select-content-available-height] min-w-[8rem] overflow-y-auto overflow-x-hidden rounded-[8px] border border-[#e6e6e6] bg-white text-[#111111] shadow-sm",
            "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 origin-[--radix-select-content-transform-origin]",
            position === "popper" &&
              "data-[side=bottom]:translate-y-1 data-[side=left]:-translate-x-1 data-[side=right]:translate-x-1 data-[side=top]:-translate-y-1",
            className
          )}
          position={position}
          {...props}
        >
          <SelectScrollUpButton />
          {enableSearch ? (
            <div className="border-b border-[#e6e6e6] p-1">
              <div className="flex h-9 items-center gap-2 rounded-[6px] border border-[#e6e6e6] px-2">
                <Search className="h-4 w-4 text-[#7f7d83]" />
                <input
                  ref={setSearchInputRef}
                  type="text"
                  value={currentSearchValue}
                  onChange={handleSearchChange}
                  onClick={(event) => {
                    event.stopPropagation()
                  }}
                  onPointerDown={(event) => {
                    event.stopPropagation()
                  }}
                  onKeyDownCapture={(event) => {
                    if (event.key !== "Escape") {
                      event.stopPropagation()
                    }
                  }}
                  onKeyUpCapture={(event) => {
                    event.stopPropagation()
                  }}
                  onKeyDown={(event) => {
                    if (event.key !== "Escape") {
                      event.stopPropagation()
                    }
                  }}
                  placeholder={searchPlaceholder}
                  aria-label="Search options"
                  className="h-full w-full border-0 bg-transparent text-[14px] leading-[20px] text-[#111111] outline-none placeholder:text-[#b3b3b3]"
                />
              </div>
            </div>
          ) : null}
          <SelectPrimitive.Viewport
            className={cn(
              "p-1",
              position === "popper" &&
                "w-full min-w-[var(--radix-select-trigger-width)]"
            )}
          >
            <SelectSearchContext.Provider value={searchContextValue}>
              {children}
            </SelectSearchContext.Provider>
          </SelectPrimitive.Viewport>
          <SelectScrollDownButton />
        </SelectPrimitive.Content>
      </SelectPrimitive.Portal>
    )
  }
)
SelectContent.displayName = SelectPrimitive.Content.displayName

const SelectLabel = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Label>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Label
    ref={ref}
    className={cn("px-2 py-1 text-[12px] font-medium text-[#7f7d83]", className)}
    {...props}
  />
))
SelectLabel.displayName = SelectPrimitive.Label.displayName

const SelectItem = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item>
>(({ className, children, ...props }, ref) => {
  const { enabled, query } = React.useContext(SelectSearchContext)
  const itemText = getNodeText(children).toLowerCase()
  const isHidden = enabled && query.length > 0 && !itemText.includes(query)

  return (
    <SelectPrimitive.Item
      ref={ref}
      className={cn(
        "relative flex w-full cursor-default select-none items-center rounded-[6px] py-2 pl-2 pr-8 text-[14px] leading-[20px] outline-none",
        "focus:bg-[#f1f1f1] focus:text-[#111111] data-[state=checked]:bg-[#f1f1f1] data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        isHidden && "hidden",
        className
      )}
      {...props}
    >
      <span className="absolute right-2 flex h-3.5 w-3.5 items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <Check className="h-4 w-4 text-[#26453f]" />
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    </SelectPrimitive.Item>
  )
})
SelectItem.displayName = SelectPrimitive.Item.displayName

const SelectSeparator = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Separator
    ref={ref}
    className={cn("-mx-1 my-1 h-px bg-[#e6e6e6]", className)}
    {...props}
  />
))
SelectSeparator.displayName = SelectPrimitive.Separator.displayName

export {
  Select,
  SelectGroup,
  SelectValue,
  SelectTrigger,
  SelectContent,
  SelectLabel,
  SelectItem,
  SelectSeparator,
  SelectScrollUpButton,
  SelectScrollDownButton,
}
